pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;

    function setUp() public { c = new PhiNFT1155(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        address storedOwner = c.owner();

        vm.prank(caller);
        address ownerSeenByCaller = c.owner();

        assertTrue(ownerSeenByCaller == storedOwner);
    }
}
